// Water logistics runs six times slower than the guard clock for playable tank autonomy.
export const waterMinutes=guardMinutes=>guardMinutes/6;
// Débits nominaux retenus pour la simulation, en litres par minute.
export const NOZZLES={ldt:{label:'LDT',flow:150,max:1},small:{label:'Petite lance',flow:250,max:2},large:{label:'Grosse lance',flow:500,max:2}};
export const TANKS={FPT:3000,CCF:4000};
export function initWater(e){e.capacity=e.tankCapacity??TANKS[e.kind]??0;e.water=e.capacity;e.nozzles={ldt:0,small:0,large:0};e.hydrant=null;e.flow=0;e.hoses=Object.entries(NOZZLES).flatMap(([key,n])=>Array.from({length:n.max},(_,index)=>({key,index,progress:0})));e.supplyProgress=0;e.supplyHydrant=null;e.supplyAnchor=null;e.supplyRoute=null;e.supplyOrigin=null;e.supplyLength=0;e.supplyDuration=20;e.supplyPackDuration=15;}
export function nozzleLimit(e){const supply=!e.longSupplyProvider&&(e.hydrant?e.supplyProgress<1:e.supplyProgress>0);const commandCrew=e.kind==='FPT'?2:0,limit=e.kind==='FPT'?(e.lightPump?1:2):Infinity;return Math.min(limit,Math.max(0,Math.floor(((e.crew??e.size??6)-commandCrew-(e.perimeterCrew||0)-(e.buildingCrew||0)-(e.ventilationCrew||0)-(e.rescueCrew||0)-(e.extricationTask!=null?2:0)-(supply?2:0))/2)));}
export function nozzleCount(e){return Object.values(e.nozzles||{}).reduce((a,b)=>a+b,0);}
export function nozzleAllowed(e,key,count){return count<=(e.nozzles?.[key]||0)||nozzleCount(e)-(e.nozzles?.[key]||0)+count<=nozzleLimit(e);}
export function staffedHoses(e){return (e.hoses||[]).filter(h=>h.index<e.nozzles[h.key]).slice(0,nozzleLimit(e));}
export function setNozzle(e,key,count){if(e.noria||e.tacticalPlacement==='Aspiration au lac'&&count>0||e.kind==='CCGC'||!NOZZLES[key]||e.status!=='scene'||!e.capacity)return false;if(!Number.isFinite(count)||!nozzleAllowed(e,key,count))return false;e.nozzles[key]=Math.max(0,Math.min(NOZZLES[key].max,Math.floor(count)));return true;}
export function tickWater(e,minutes){const ground=Object.entries(NOZZLES).reduce((sum,[key,n])=>sum+n.flow*staffedHoses(e).filter(h=>h.key===key&&h.progress>=1).length,0),external=e.aerialDemand||0,requested=ground+external;const incoming=e.hydrant&&e.supplyProgress>=1?1000:0;const available=e.water+incoming*minutes,total=minutes>0?Math.min(requested,available/minutes):0,factor=requested?total/requested:0;e.flow=ground*factor;e.externalFlow=external*factor;e.pumpFlow=total;e.water=Math.max(0,Math.min(e.capacity,available-total*minutes));return e.flow;}
export function stow(e){e.foamOn=false;e.foamFlow=0;e.nozzles={ldt:0,small:0,large:0};e.hydrant=null;e.flow=0;e.externalFlow=0;e.pumpFlow=0;e.aerialDemand=0;}

export function tickEquipment(e,minutes){if(!e.hoses)return;if(e.hydrant&&e.supplyHydrant!==e.hydrant){e.supplyHydrant=e.hydrant;e.supplyAnchor=e.hydrant.position.clone();e.supplyRoute=null;e.supplyOrigin=null;e.supplyDuration=20;e.supplyPackDuration=15;}if(!e.hydrant&&e.supplyProgress===0){e.supplyHydrant=null;e.supplyAnchor=null;e.supplyRoute=null;e.supplyOrigin=null;e.supplyLength=0;}for(const h of e.hoses){const wanted=h.index<e.nozzles[h.key];if(wanted&&!staffedHoses(e).includes(h))continue;h.progress=Math.max(0,Math.min(1,h.progress+minutes*(wanted?1/({ldt:12,small:20,large:28}[h.key]):-1/15)));}e.supplyProgress=Math.max(0,Math.min(1,(e.supplyProgress||0)+minutes*(e.hydrant?1/(e.supplyDuration||20):-1/(e.supplyPackDuration||15))));}
export function equipmentBusy(e){return e.hoses?.some(h=>h.index<e.nozzles[h.key]?h.progress<1:h.progress>0)||!!(e.hydrant?e.supplyProgress<1:e.supplyProgress>0);}
export function equipmentStatus(e){const laying=e.hoses?.some(h=>h.index<e.nozzles[h.key]&&h.progress<1),packing=e.hoses?.some(h=>h.index>=e.nozzles[h.key]&&h.progress>0);return laying?'Établissement des tuyaux et lances':packing?'Rangement des tuyaux et lances':e.hydrant&&e.supplyProgress<1?(e.hydrant.userData?.supplyKind==='lake'?'Installation des aspiraux':'Raccordement au poteau'):!e.hydrant&&e.supplyProgress>0?'Rangement de l’alimentation':'';}
